static std::random_device rd;
    static std::mt19937 gen(rd());
    std::uniform_real_distribution<double> dist_prob(0.0, 1.0);

    double prob = 1.0 - std::exp(-collisionFreq * dt);

    for (size_t i = 0; i < velocities.size(); ++i) {
        if (dist_prob(gen) < prob) {
            double sigma = std::sqrt(targetTemp / masses[i]);
            std::normal_distribution<double> dist_vel(0.0, sigma);

            velocities[i].x = dist_vel(gen);
            velocities[i].y = dist_vel(gen);
            velocities[i].z = dist_vel(gen);
        }
    }

double prob = 1.0 - std::exp(-collisionFreq * dt);
for (size_t i = 0; i < velocities.size(); ++i) {
    double r = (double)std::rand() / (double)RAND_MAX;
    if (r < prob) {
        double sigma = std::sqrt(targetTemp / masses[i]);

        // Box-Muller transform for 3 independent Gaussian variables
        for (int dim = 0; dim < 3; ++dim) {
            double u1 = (double)std::rand() / (double)RAND_MAX;
            double u2 = (double)std::rand() / (double)RAND_MAX;
            // Ensure u1 is not 0 to avoid log(0)
            if (u1 <= 0.0) u1 = 1e-10;

            double z = std::sqrt(-2.0 * std::log(u1)) * std::cos(2.0 * M_PI * u2);
            if (dim == 0) velocities[i].x = z * sigma;
            else if (dim == 1) velocities[i].y = z * sigma;
            else velocities[i].z = z * sigma;
        }
    }
}

